    else if (e && typeof e === 'object') msg = [e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error';
    else msg = String(e || 'unknown error');
    out.push({ json: { ok: false, error: msg.slice(0, 400) } });
    continue;
  }
  const lower = {};
  for (const k of Object.keys(j)) lower[k.toLowerCase()] = k;
  const o = {};
  for (const k of KEEP) {
    const real = Object.prototype.hasOwnProperty.call(j, k) ? k : lower[k.toLowerCase()];
    const v = real ? j[real] : undefined;
    if (v === undefined || v === null || v === '') continue;
    o[k] = (typeof v === 'string' && v.length > 300) ? v.slice(0, 300) + '\u2026' : v;
  }
  if (Object.keys(o).length) out.push({ json: o });
}
return out.length ? out : [{ json: { ok: true, note: 'no results' } }];

