// OTHVM — Drive download: نصي → content (أول 8000 حرف)، غير كده ميتاداتا فقط بدون binary
const out = [];
const all = $input.all();
for (let i = 0; i < all.length; i++) {
  const item = all[i];
  const j = item.json || {};
  const bin = (item.binary && item.binary.data) || null;
  const meta = bin || {};
  const rec = {
    ok: true,
    id: j.fileId || j.id || meta.id || null,
    name: meta.fileName || j.name || null,
    mimeType: meta.mimeType || j.mimeType || null,
    size: (typeof meta.bytes === 'number') ? meta.bytes : (Number(meta.fileSize) || j.size || null),
  };
  if (bin) {
    const mime = String(rec.mimeType || '');
    const size = Number(rec.size) || 0;
    const textLike =
      mime.indexOf('text/') === 0 ||
      mime.indexOf('json') >= 0 ||
      mime.indexOf('xml') >= 0 ||
      mime.indexOf('csv') >= 0 ||
      mime.indexOf('javascript') >= 0 ||
      mime.indexOf('markdown') >= 0;
    if (size > 2000000) {
      rec.note = 'الملف كبير (أكبر من 2 ميجا) — ميتاداتا فقط';
    } else if (textLike || (size && size <= 100000)) {
      try {
        const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
        let text = buf.toString('utf8');
        if (buf.length >= 3 && buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF) text = text.slice(3);
        rec.content = text.slice(0, 8000);
      } catch (e) {
        rec.content = null;
        rec.note = 'تعذر قراءة المحتوى — ميتاداتا فقط';
      }
    } else {
      rec.note = 'ملف ثنائي — ميتاداتا فقط بدون محتوى';
    }
  } else {
    rec.note = 'مفيش binary في نتيجة التحميل';
  }
  out.push({ json: rec });
}
return out;

